export const COUNTRY_OPTIONS=[...new Set(DIRECTORY.map(r=>r[0]))].map(code=>({code,name:code==='INT'?'International':new Intl.DisplayNames(['en'],{type:'region'}).of(code)})).sort((a,b)=>a.name.localeCompare(b.name));
export function expandedTemplates(){return [...SOURCE_STARTERS,...DIRECTORY.flatMap(([region,destination,title,url],index)=>['Initial ICSR','Follow-up ICSR','Clinical safety report','Periodic / aggregate','Safety issue / signal','Device / combination-product'].map((reportType,n)=>{const id='research-'+region.toLowerCase()+'-'+index+'-'+n;return {id,title:region+' · '+destination+' · '+reportType+' research',region,countries:[region],agency:destination,destination,reportType,scope:n===2?'clinical':'marketed',productType:n===5?'Devices / combinations':'Human medicines',evidence:'research',description:'Research worksheet only. No local reporting obligation or deadline has been established.',source:{title,url,edition:'Reference entry point only; exact provision not established',location:'Find current legal provision, scope and reporting entity',checkedOn:'',effective:'',verified:false},rule:{key:id.toUpperCase(),country:region,license:'',destination:destination==='Authority to identify'?'':destination,clockStart:'',days:'',dayType:'',format:'',condition:'',scheduling:'',priority:''},limits:['This listing does not establish that the organization receives this report type. International bodies may be reference organizations only.','Confirm authority, current law, product scope, domestic/foreign territory, minimum criteria, clock, initial/follow-up distinctions, exceptions and dates.'],schema:'pvinfo-rule-template/1',version:1,status:'Research required',history:[{version:1,date:'2026-11-06',reason:'Blank research worksheet; no regulatory requirement asserted.'}]};}))].map(t=>({...t,schema:'pvinfo-rule-template/1',version:1,status:t.evidence==='research'?'Research required':'Source-linked starter · human review required',history:t.history??[{version:1,date:'2026-11-06',reason:'Source-linked draft; company applicability requires review.'}]}));}
